<template>
  <section class="advanced-workspace" v-loading="loading">
    <div class="section-head"><div><span>04 / 批量与智能工作流</span><h2>生产力中心</h2></div><div class="workspace-actions"><div class="current-document"><el-icon><Document /></el-icon><span>当前处理：</span><strong>{{ targetLabel }}</strong></div><el-button text @click="loadAll"><el-icon><Refresh /></el-icon> 刷新</el-button></div></div>
    <div class="advanced-grid">
      <article class="advanced-card"><div class="card-title"><el-icon><Files /></el-icon><div><strong>批量处理</strong><small>选择多份文档生成统一摘要</small></div></div><el-select v-model="batchIds" multiple filterable collapse-tags placeholder="选择文档" class="wide"><el-option v-for="doc in documents" :key="doc.id" :label="titleOf(doc)" :value="String(doc.id)" /></el-select><el-button type="primary" plain :loading="batchLoading" @click="runBatchSummary">批量生成摘要</el-button></article>
      <article class="advanced-card"><div class="card-title"><el-icon><DocumentAdd /></el-icon><div><strong>文档模板</strong><small>会议纪要、周报、需求文档</small></div></div><el-select v-model="templateType" class="wide"><el-option label="会议纪要" value="meeting" /><el-option label="项目周报" value="weekly" /><el-option label="需求文档" value="requirement" /><el-option label="项目报告" value="report" /></el-select><el-button type="primary" plain @click="createTemplate">创建模板文档</el-button></article>
      <article class="advanced-card meeting-audio-card"><div class="card-title"><el-icon><Microphone /></el-icon><div><strong>录音会议纪要</strong><small>上传录音，自动转写并由 AI 整理待办与决策</small></div></div><input ref="audioInput" class="hidden-image-input" type="file" accept="audio/mpeg,audio/wav,audio/x-wav,audio/mp4,audio/aac,audio/ogg,audio/webm" @change="selectAudio" /><el-input v-model="meetingTitle" maxlength="60" show-word-limit placeholder="会议名称（可选）" /><div class="audio-source"><el-button plain @click="audioInput?.click()"><el-icon><UploadFilled /></el-icon> 选择录音</el-button><span :title="audioFile?.name">{{ audioFile ? `${audioFile.name} · ${audioSize}` : '支持 MP3、WAV、M4A、AAC、OGG、WebM（约 7MB / 5 分钟内）' }}</span></div><el-select v-model="audioLanguage" class="wide"><el-option label="自动识别语言" value="auto" /><el-option label="中文" value="zh" /><el-option label="英语" value="en" /><el-option label="日语" value="ja" /><el-option label="韩语" value="ko" /></el-select><el-button type="primary" plain :loading="meetingLoading" :disabled="!audioFile" @click="createAudioMinutes">{{ meetingLoading ? '正在转写并生成纪要…' : '生成并保存会议纪要' }}</el-button></article><article class="advanced-card"><div class="card-title"><el-icon><MagicStick /></el-icon><div><strong>AI 改写</strong><small>扩写、压缩、风格转换与中英互译</small></div></div><p class="card-target">处理对象：{{ targetLabel }}</p><el-select v-model="rewriteMode" class="wide"><el-option v-for="item in rewriteModes" :key="item.value" :label="item.label" :value="item.value" /></el-select><el-button type="primary" plain :loading="rewriteLoading" @click="rewrite">改写当前文本</el-button></article>
      <article class="advanced-card image-card"><div class="card-title"><el-icon><Picture /></el-icon><div><strong>图片处理</strong><small>压缩、裁剪、旋转、转 PDF、合成长图</small></div></div><input ref="imageInput" class="hidden-image-input" type="file" accept="image/jpeg,image/png,image/webp" multiple @change="selectImages" /><div class="image-source"><el-button plain @click="imageInput?.click()"><el-icon><UploadFilled /></el-icon> 选择图片</el-button><span>{{ imageFiles.length ? `已选 ${imageFiles.length} 张` : '支持 JPG、PNG、WebP' }}</span></div><el-select v-model="imageOperation" class="wide"><el-option label="图片压缩" value="compress" /><el-option label="居中裁剪" value="crop" /><el-option label="旋转图片" value="rotate" /><el-option label="图片转 PDF" value="pdf" /><el-option label="合并成长图" value="merge" /></el-select><div v-if="imageOperation === 'compress'" class="image-options"><span>压缩质量</span><el-slider v-model="imageQuality" :min="35" :max="95" :show-tooltip="true" /></div><div v-else-if="imageOperation === 'crop'" class="image-options crop-options"><el-input-number v-model="cropWidth" :min="100" :max="8000" controls-position="right" /><span>×</span><el-input-number v-model="cropHeight" :min="100" :max="8000" controls-position="right" /></div><div v-else-if="imageOperation === 'rotate'" class="image-options"><el-radio-group v-model="rotation"><el-radio-button :label="90">90°</el-radio-button><el-radio-button :label="180">180°</el-radio-button><el-radio-button :label="270">270°</el-radio-button></el-radio-group></div><p class="image-hint">{{ imageHint }}</p><el-button type="primary" plain :loading="imageProcessing" :disabled="!imageFiles.length" @click="processImages">{{ imageProcessing ? '正在处理…' : imageActionLabel }}</el-button></article>
      <article class="advanced-card"><div class="card-title"><el-icon><DataAnalysis /></el-icon><div><strong>质量与安全检查</strong><small>结构、重复与敏感信息</small></div></div><p class="card-target">检查对象：{{ targetLabel }}</p><div class="quality"><span>标题层级 {{ quality.headings }} 项</span><span>重复段 {{ quality.duplicates }} 处</span><span>风险项 {{ quality.risks }} 个</span></div><el-button plain @click="inspect">生成质量报告</el-button></article>
      <article class="advanced-card"><div class="card-title"><el-icon><Connection /></el-icon><div><strong>多文档分析</strong><small>找出共同主题与冲突点</small></div></div><el-select v-model="analysisIds" multiple filterable collapse-tags placeholder="至少选择两份文档" class="wide"><el-option v-for="doc in documents" :key="doc.id" :label="titleOf(doc)" :value="String(doc.id)" /></el-select><el-button plain :loading="analysisLoading" @click="analyzeMany">生成分析报告</el-button></article>
      <article class="advanced-card"><div class="card-title"><el-icon><Collection /></el-icon><div><strong>知识库索引</strong><small>{{ indexedIds.length }} 份文档已建立索引</small></div></div><el-select v-model="indexId" filterable placeholder="选择文档加入知识库" class="wide"><el-option v-for="doc in documents" :key="doc.id" :label="titleOf(doc)" :value="String(doc.id)" /></el-select><div class="button-pair"><el-button type="primary" plain :loading="indexLoading" @click="indexDocument">加入知识库</el-button><el-button plain @click="removeIndex" :disabled="!indexId">移出索引</el-button></div></article>
    </div>
    <div class="history"><div><strong>任务中心</strong><small>保留本浏览器中的处理记录</small></div><el-empty v-if="history.length===0" description="还没有处理记录" :image-size="48" /><div v-else class="history-list"><div v-for="item in history.slice(0,8)" :key="item.id"><span class="history-dot"></span><strong>{{ item.title }}</strong><small>{{ item.time }}</small><em>{{ item.status }}</em></div></div></div>
    <el-dialog v-model="resultVisible" title="SmartDoc 处理结果" width="620px"><pre class="advanced-result">{{ output }}</pre><template #footer><el-button @click="resultVisible=false">关闭</el-button><el-button type="primary" @click="copyOutput">复制</el-button></template></el-dialog>
  </section>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { docApi } from '../../api/document'
import { aiApi } from '../../api/ai'

const props = defineProps({ currentContent: { type: String, default: '' }, currentDocument: { type: Object, default: null } })
const emit = defineEmits(['apply'])
const documents=ref([]), batchIds=ref([]), analysisIds=ref([]), indexId=ref(''), indexedIds=ref([]), templateType=ref('meeting'), rewriteMode=ref('expand'), loading=ref(false), batchLoading=ref(false), rewriteLoading=ref(false), analysisLoading=ref(false), indexLoading=ref(false), output=ref(''), resultVisible=ref(false)
const history=ref(JSON.parse(localStorage.getItem('smartdoc_tool_history')||'[]'))
const quality=ref({headings:0,duplicates:0,risks:0})
const rewriteModes=[{value:'expand',label:'扩写为完整说明'},{value:'compress',label:'压缩为核心要点'},{value:'formal',label:'正式化表达'},{value:'colloquial',label:'口语化表达'},{value:'zh-en',label:'中文 → English'},{value:'en-zh',label:'English → 中文'}]
const imageInput=ref(null), imageFiles=ref([]), imageOperation=ref('compress'), imageQuality=ref(78), rotation=ref(90), cropWidth=ref(1200), cropHeight=ref(800), imageProcessing=ref(false)
const audioInput=ref(null), audioFile=ref(null), meetingTitle=ref(''), audioLanguage=ref('auto'), meetingLoading=ref(false)
const audioSize=computed(()=>audioFile.value?`${(audioFile.value.size/1024/1024).toFixed(audioFile.value.size>1024*1024?1:2)} ${audioFile.value.size>1024*1024?'MB':'KB'}`:'')
const imageHint=computed(()=>({compress:'保持画面尺寸，压缩后下载 JPG 文件。',crop:'从图片中心裁剪为指定的宽高，超出原图会自动取可用区域。',rotate:'按选择角度旋转每一张图片并下载。',pdf:'将选中的图片按顺序转换为一个多页 PDF。',merge:'将选中的图片按顺序拼接成一张长图。'}[imageOperation.value]))
const imageActionLabel=computed(()=>({compress:'压缩并下载',crop:'裁剪并下载',rotate:'旋转并下载',pdf:'生成 PDF',merge:'合成长图'}[imageOperation.value]))
const targetLabel=computed(()=>props.currentDocument?.title||props.currentDocument?.name||(props.currentContent.trim()?'当前文本草稿（未关联文档）':'未选择文档'))
const titleOf=d=>d?.title||d?.name||'未命名文档'; const data=r=>r?.data??r??{}; const user=()=>localStorage.getItem('userId')
function record(title,status='已完成'){history.value.unshift({id:Date.now()+Math.random(),title,status,time:new Date().toLocaleString()});history.value=history.value.slice(0,30);localStorage.setItem('smartdoc_tool_history',JSON.stringify(history.value))}
async function loadAll(){loading.value=true;try{documents.value=data(await docApi.getUserDocs(user()))||[];indexedIds.value=data(await aiApi.getIndexedDocuments())||[]}catch(e){ElMessage.error('读取工具箱数据失败')}finally{loading.value=false}}
async function contents(ids){return Promise.all(ids.map(async id=>{const d=data(await docApi.getDocDetail(id));return `【${titleOf(d)}】\n${d.content||''}`}))}
function show(text,title='处理完成'){output.value=text;resultVisible.value=true;record(title)}
async function runBatchSummary(){if(!batchIds.value.length)return ElMessage.warning('请选择至少一份文档');batchLoading.value=true;try{const text=(await contents(batchIds.value)).join('\n\n').slice(0,24000);const r=data(await aiApi.summarizeText(text,600));show(r.summary||r.content||JSON.stringify(r),'批量摘要')}catch(e){ElMessage.error('批量处理失败')}finally{batchLoading.value=false}}
async function createTemplate(){const map={meeting:['会议纪要','会议主题：\n会议时间：\n参会人员：\n\n## 核心讨论\n\n## 决策事项\n\n## 待办事项\n| 事项 | 负责人 | 截止时间 |\n| --- | --- | --- |'],weekly:['项目周报','本周完成：\n\n下周计划：\n\n风险与阻塞：\n\n需要协调支持：'],requirement:['需求文档','## 背景与目标\n\n## 用户场景\n\n## 功能需求\n\n## 验收标准\n\n## 风险与边界'],report:['项目报告','## 项目概述\n\n## 关键成果\n\n## 数据与分析\n\n## 问题与改进\n\n## 后续计划']}[templateType.value];try{const r=data(await docApi.createDoc({title:map[0],content:map[1],category:'template'}));await loadAll();show(map[1],'模板已创建');emit('apply',map[1]);indexId.value=String(r.id||'')}catch(e){ElMessage.error('模板创建失败')}}
function splitRewriteText(content,maxLength=2400){const parts=[],paragraphs=String(content||'').split(/\n{2,}/);let current='';for(const paragraph of paragraphs){const text=paragraph.trim();if(!text)continue;if((current+'\n\n'+text).length<=maxLength){current+=`${current?'\n\n':''}${text}`;continue}if(current){parts.push(current);current=''}for(let index=0;index<text.length;index+=maxLength)parts.push(text.slice(index,index+maxLength))}if(current)parts.push(current);return parts.length?parts:[String(content||'')]}
async function rewrite(){if(!props.currentContent.trim())return ElMessage.warning('请先在上方选择或输入文本');rewriteLoading.value=true;try{const instructions={expand:'扩写为完整、清晰的说明，补足必要衔接但不得编造事实',compress:'压缩为简洁的核心要点，保留关键信息和结论',formal:'改写为正式、专业的书面表达，保持原意',colloquial:'改写为自然、易懂的口语化表达，保持原意','zh-en':'翻译为自然专业的英语','en-zh':'翻译为自然准确的中文'};const results=[];const chunks=splitRewriteText(props.currentContent);for(let index=0;index<chunks.length;index+=1){const prompt=`请将下面文本${instructions[rewriteMode.value]}。保留段落、标题、编号和列表；只输出处理后的正文，不要解释。\n\n原文：\n${chunks[index]}`;const r=data(await aiApi.chatText(prompt,'deepseek-chat'));const text=typeof r==='string'?r:(r.content||r.answer||r.finalAnswer||'');if(!String(text).trim())throw new Error(`第 ${index+1} 段未返回结果`);results.push(String(text).trim())}const text=results.join('\n\n');show(text,'AI 改写');emit('apply',text)}catch(e){ElMessage.error(e.message||'AI 改写失败')}finally{rewriteLoading.value=false}}
function inspect(){const lines=props.currentContent.split('\n').filter(Boolean), seen=new Set();let dup=0;lines.forEach(l=>{const k=l.replace(/\s/g,'');if(seen.has(k))dup++;seen.add(k)});quality.value={headings:lines.filter(l=>/^#|^第[一二三四五六七八九十\d]+/.test(l)).length,duplicates:dup,risks:(props.currentContent.match(/1[3-9]\d{9}|[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/g)||[]).length};show(`文档质量报告\n\n标题层级：${quality.value.headings} 项\n重复段落：${dup} 处\n敏感信息风险：${quality.value.risks} 项\n总字数：${props.currentContent.length} 字`,'质量检查')}
async function analyzeMany(){if(analysisIds.value.length<2)return ElMessage.warning('至少选择两份文档');analysisLoading.value=true;try{const text=(await contents(analysisIds.value)).join('\n\n').slice(0,24000);const r=data(await aiApi.executeAgent({task:`分析以下多份文档，输出：共同主题、相互矛盾或不一致点、可统一的结论。\n\n${text}`,context:{source:'toolbox-multi-analysis'}}));show(r.finalAnswer||r.answer||r.content||JSON.stringify(r),'多文档分析')}catch(e){ElMessage.error('多文档分析失败')}finally{analysisLoading.value=false}}
async function indexDocument(){if(!indexId.value)return ElMessage.warning('请选择一份文档');indexLoading.value=true;try{const d=data(await docApi.getDocDetail(indexId.value));if(!d.content)return ElMessage.warning('该文档尚无正文，请先完成 OCR 或录入内容');await aiApi.indexWithSegment(indexId.value,d.content,'AUTO');await loadAll();record('知识库索引');ElMessage.success('已加入知识库')}catch(e){ElMessage.error('索引失败')}finally{indexLoading.value=false}}
async function removeIndex(){try{await aiApi.removeIndexedDocument(indexId.value);await loadAll();record('移出知识库');ElMessage.success('已移出知识库')}catch(e){ElMessage.error('移除失败')}}
function selectAudio(event){const file=(event.target.files||[])[0];if(!file)return;if(!file.type.startsWith('audio/')){ElMessage.warning('请选择音频录音文件');return}if(file.size>7*1024*1024){ElMessage.warning('DashScope 直传录音不能超过约 7MB');return}audioFile.value=file;event.target.value=''}
async function createAudioMinutes(){if(!audioFile.value)return;meetingLoading.value=true;try{const result=data(await aiApi.createMeetingMinutesFromAudio(audioFile.value,meetingTitle.value,audioLanguage.value));const title=(meetingTitle.value.trim()||audioFile.value.name.replace(/\.[^.]+$/,''))+' - 会议纪要';const content=`${result.minutes||''}\n\n---\n\n## 原始转写\n\n${result.transcript||''}`;const created=data(await docApi.createDoc({title,content,category:'meeting-minutes'}));await loadAll();show(content,'录音会议纪要');emit('apply',content);ElMessage.success(`会议纪要已保存${created?.id?'到文档库':''}`)}catch(error){ElMessage.error(error.message||'录音会议纪要生成失败')}finally{meetingLoading.value=false}}function selectImages(event){const files=Array.from(event.target.files||[]).filter(file=>file.type.startsWith('image/'));imageFiles.value=files;if(!files.length)ElMessage.warning('请选择 JPG、PNG 或 WebP 图片');event.target.value=''}
function loadImage(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{URL.revokeObjectURL(url);resolve(image)};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error(`${file.name} 无法读取`))};image.src=url})}
function canvasForImage(image,width=image.naturalWidth,height=image.naturalHeight){const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width));canvas.height=Math.max(1,Math.round(height));const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);return canvas}
function canvasBlob(canvas,type='image/jpeg',quality=.82){return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('图片编码失败')),type,quality))}
function downloadBlob(blob,fileName){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=fileName;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),600)}
function baseName(fileName){return String(fileName||'image').replace(/\.[^.]+$/,'')}
async function compressImage(file){const image=await loadImage(file);const blob=await canvasBlob(canvasForImage(image),'image/jpeg',imageQuality.value/100);downloadBlob(blob,`${baseName(file.name)}-compressed.jpg`)}
async function cropImage(file){const image=await loadImage(file);const width=Math.min(Number(cropWidth.value)||image.naturalWidth,image.naturalWidth),height=Math.min(Number(cropHeight.value)||image.naturalHeight,image.naturalHeight),x=Math.max(0,Math.floor((image.naturalWidth-width)/2)),y=Math.max(0,Math.floor((image.naturalHeight-height)/2));const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,width,height);context.drawImage(image,x,y,width,height,0,0,width,height);downloadBlob(await canvasBlob(canvas),'${baseName(file.name)}-cropped.jpg'.replace('${baseName(file.name)}',baseName(file.name)))}
async function rotateImage(file){const image=await loadImage(file),angle=Number(rotation.value),swap=angle===90||angle===270,canvas=document.createElement('canvas');canvas.width=swap?image.naturalHeight:image.naturalWidth;canvas.height=swap?image.naturalWidth:image.naturalHeight;const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.translate(canvas.width/2,canvas.height/2);context.rotate(angle*Math.PI/180);context.drawImage(image,-image.naturalWidth/2,-image.naturalHeight/2);downloadBlob(await canvasBlob(canvas),'${baseName(file.name)}-rotated.jpg'.replace('${baseName(file.name)}',baseName(file.name)))}
function bytes(...parts){const length=parts.reduce((sum,part)=>sum+part.length,0),output=new Uint8Array(length);let offset=0;parts.forEach(part=>{output.set(part,offset);offset+=part.length});return output}
function textBytes(value){return new TextEncoder().encode(value)}
function buildPdf(pages){const objects=[],encoder=new TextEncoder(),pageWidth=595.28,pageHeight=841.89,margin=28;objects[1]=textBytes('<< /Type /Catalog /Pages 2 0 R >>');const pageIds=pages.map((_,index)=>3+index),imageStart=3+pages.length,contentStart=imageStart+pages.length;objects[2]=textBytes(`<< /Type /Pages /Kids [${pageIds.map(id=>`${id} 0 R`).join(' ')}] /Count ${pages.length} >>`);pages.forEach((page,index)=>{const pageId=pageIds[index],imageId=imageStart+index,contentId=contentStart+index,scale=Math.min((pageWidth-margin*2)/page.width,(pageHeight-margin*2)/page.height),width=page.width*scale,height=page.height*scale,x=(pageWidth-width)/2,y=(pageHeight-height)/2,content=`q\n${width.toFixed(2)} 0 0 ${height.toFixed(2)} ${x.toFixed(2)} ${y.toFixed(2)} cm\n/Im0 Do\nQ`;objects[pageId]=textBytes(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pageWidth} ${pageHeight}] /Resources << /XObject << /Im0 ${imageId} 0 R >> >> /Contents ${contentId} 0 R >>`);objects[imageId]=bytes(textBytes(`<< /Type /XObject /Subtype /Image /Width ${page.width} /Height ${page.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${page.jpeg.length} >>\nstream\n`),page.jpeg,textBytes('\nendstream'));objects[contentId]=textBytes(`<< /Length ${encoder.encode(content).length} >>\nstream\n${content}\nendstream`)});const chunks=[textBytes('%PDF-1.4\n')],offsets=[0];let offset=chunks[0].length;for(let id=1;id<objects.length;id+=1){const object=bytes(textBytes(`${id} 0 obj\n`),objects[id],textBytes('\nendobj\n'));offsets[id]=offset;chunks.push(object);offset+=object.length}const xref=offset;chunks.push(textBytes(`xref\n0 ${objects.length}\n0000000000 65535 f \n${offsets.slice(1).map(value=>`${String(value).padStart(10,'0')} 00000 n \n`).join('')}trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`));return new Blob([bytes(...chunks)],{type:'application/pdf'})}
async function imagesToPdf(files){const pages=[];for(const file of files){const image=await loadImage(file),blob=await canvasBlob(canvasForImage(image),'image/jpeg',.88);pages.push({width:image.naturalWidth,height:image.naturalHeight,jpeg:new Uint8Array(await blob.arrayBuffer())})}return buildPdf(pages)}
async function mergeImages(files){const images=[];for(const file of files)images.push(await loadImage(file));let width=Math.max(...images.map(image=>image.naturalWidth)),height=images.reduce((sum,image)=>sum+image.naturalHeight*width/image.naturalWidth,0),scale=Math.min(1,30000/height,16000/width);width=Math.max(1,Math.floor(width*scale));height=Math.max(1,Math.floor(height*scale));const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,width,height);let top=0;images.forEach(image=>{const imageHeight=Math.round(image.naturalHeight*width/image.naturalWidth);context.drawImage(image,0,top,width,imageHeight);top+=imageHeight});return canvasBlob(canvas,'image/png')}
async function processImages(){if(!imageFiles.value.length)return;imageProcessing.value=true;try{if(imageOperation.value==='pdf'){downloadBlob(await imagesToPdf(imageFiles.value),'smartdoc-images.pdf')}else if(imageOperation.value==='merge'){downloadBlob(await mergeImages(imageFiles.value),'smartdoc-long-image.png')}else{for(const file of imageFiles.value){if(imageOperation.value==='compress')await compressImage(file);if(imageOperation.value==='crop')await cropImage(file);if(imageOperation.value==='rotate')await rotateImage(file)}}record(`图片${imageActionLabel.value}`);ElMessage.success('图片处理完成，结果已开始下载')}catch(error){ElMessage.error(error.message||'图片处理失败')}finally{imageProcessing.value=false}}
async function copyOutput(){try{await navigator.clipboard.writeText(output.value);ElMessage.success('已复制')}catch(e){ElMessage.warning('请手动复制')}}
onMounted(loadAll)
</script>

